if term.isColor() then term.setTextColor(colors.white) end
print("On a new computer:  pastebin run <installer code> <role> <join code>")
]]
FILES["bin/report.lua"] = [[
-- report: bundles everything needed to debug this computer into one text and uploads
-- it to pastebin as UNLISTED (not public) with a one-week expiry. The secret is removed.
--   /fleet/bin/report            upload and print the link
--   /fleet/bin/report --file     only write /fleet/data/report.txt
package.path = "/fleet/?.lua;" .. package.path
local D = require("lib.doctor")
local config = require("lib.config")
local store = require("lib.store")
local Up = require("lib.update")

local args = { ... }
local fileOnly = args[1] == "--file"
local out = {}
local function add(s) out[#out + 1] = s end
local function section(title) add("") add("== " .. title .. " ==") end

local function tail(path, n)
  local s = store.readFile(path)
  if not s then return nil end
  local lines = {}
  for line in (s .. "\n"):gmatch("(.-)\n") do lines[#lines + 1] = line end
  if lines[#lines] == "" then lines[#lines] = nil end
  local from = math.max(1, #lines - n + 1)
  return table.concat(lines, "\n", from, #lines), #lines - from + 1
end

print("Collecting report (runs the doctor checks)...")
add("TurtleGPS report")
add(("computer #%d  label %s  %s"):format(os.getComputerID(), tostring(os.getComputerLabel()), _HOST or os.version()))
add(("code %s   time %d (epoch ms)"):format(Up.myVersion(), os.epoch("utc")))

section("Config (secret removed)")
local cfg, cfgErr = config.load()
if cfg then
  local copy = {}
  for k, v in pairs(cfg) do copy[k] = v end
  copy.secret = cfg.secret and ("<removed, " .. #cfg.secret .. " chars>") or nil
  add(config.pretty(copy, 0))
else
  add("unreadable: " .. tostring(cfgErr))
end

section("Peripherals")
for _, name in ipairs(peripheral.getNames()) do
  local t = peripheral.getType(name)
  local extra = ""
  if t == "monitor" then
    local m = peripheral.wrap(name)
    local w, h = m.getSize()
    extra = (" %dx%d scale %s color %s"):format(w, h, tostring(m.getTextScale and m.getTextScale()), tostring(m.isColor()))
  elseif t == "modem" then
    extra = " wireless " .. tostring(peripheral.call(name, "isWireless"))
  end
  add(name .. ": " .. tostring(t) .. extra)
end

if turtle then
  section("Turtle")
  add("fuel " .. tostring(turtle.getFuelLevel()) .. " / " .. tostring(turtle.getFuelLimit()))
  for s = 1, 16 do
    local d = turtle.getItemDetail(s)
    if d then add(("slot %d: %s x%d"):format(s, d.name, d.count)) end
  end
  add("nav: " .. tostring(store.readFile("/fleet/data/nav")))
end

section("Doctor")
local _, counts = D.run({ out = function(r) add(D.format(r)) write(".") end })
print("")
add(("%d ok, %d warnings, %d problems"):format(counts.pass, counts.warn, counts.fail))

section("Update state")
add(tostring(store.readFile("/fleet/data/update") or "none"))

local db = store.load("/fleet/data/fleet.db", nil)
if type(db) == "table" then
  section("Fleet state (control)")
  for _, a in ipairs(db.alerts or {}) do
    if a.active then add("ALERT " .. tostring(a.text)) end
  end
  for id, t in pairs(db.turtles or {}) do
    add(("turtle #%s %s %s %s,%s,%s link=%s status=%s fuel=%s ver=%s"):format(tostring(id), tostring(t.label),
      tostring(t.dim), tostring(t.x), tostring(t.y), tostring(t.z), tostring(t.link), tostring(t.status),
      tostring(t.fuel), tostring(t.ver)))
  end
  for id, g in pairs(db.gps or {}) do
    add(("gps #%s %s %s,%s,%s link=%s %s"):format(tostring(id), tostring(g.dim), tostring(g.x), tostring(g.y),
      tostring(g.z), tostring(g.link), tostring(g.verdict)))
  end
end

for _, f in ipairs({ { "/fleet/data/crash.txt", 60 }, { "/fleet/data/log.txt", 150 }, { "/fleet/data/log.txt.old", 40 } }) do
  local text, n = tail(f[1], f[2])
  if text then
    section(f[1] .. " (last " .. n .. " lines)")
    add(text)
  end
end

local text = table.concat(out, "\n") .. "\n"
store.writeFile("/fleet/data/report.txt", text)

local function upload()
  if not http then return nil, "the http API is disabled on this server" end
  local key = "0ec2eb25b6166c0c27a394ae118ad829" -- CraftOS' own pastebin key (rom/programs/http/pastebin.lua)
  local name = ("turtlegps-%d"):format(os.getComputerID())
  local body = "api_option=paste&api_dev_key=" .. key
    .. "&api_paste_private=1&api_paste_expire_date=1W&api_paste_format=text"
    .. "&api_paste_name=" .. textutils.urlEncode(name)
    .. "&api_paste_code=" .. textutils.urlEncode(text)
  local response, err = http.post("https://pastebin.com/api/api_post.php", body)
  if not response then return nil, err or "upload failed" end
  local url = response.readAll()
  response.close()
  if not url or not url:match("^https?://") then return nil, url or "no link returned" end
  return url
end

if fileOnly then
  print("Report written to /fleet/data/report.txt")
  return
end
local url, uerr = upload()
if url then
  if term.isColor() then term.setTextColor(colors.lime) end
  print("Report uploaded (unlisted, expires in a week):")
  print(url)
  if term.isColor() then term.setTextColor(colors.white) end
  store.writeFile("/fleet/data/report.url", url)
else
  printError("Upload failed: " .. tostring(uerr))
  print("Report written to /fleet/data/report.txt")
end
]]
FILES["bin/setup.lua"] = [[
-- TurtleGPS setup: writes /fleet/config.lua and /startup.lua, then reboots.
-- Run again any time to change settings:  /fleet/bin/setup
--
-- Fast path (the installer passes its arguments through):
--   setup turtle TG-7-abcd...-1f2e                 -> asks only dimension and label
--   setup gpshost TG-7-... dim=nether x=1 y=90 z=1 -y   -> asks nothing, reboots
-- Arguments: a role, a join code (press J on the control computer), key=value answers
-- (dim, label, owner, x, y, z, commanders), and -y to accept defaults without asking.

package.path = "/fleet/?.lua;" .. package.path
local config = require("lib.config")
local P = require("lib.proto")
local J = require("lib.joincode")

local ROLES = { control = true, turtle = true, pocket = true, gpshost = true }

local args = { ... }
local preset, roleArg, joinArg, yes = {}, nil, nil, false
for _, a in ipairs(args) do
  local k, v = tostring(a):match("^(%w+)=(.*)$")
  if k then preset[k] = v
  elseif a == "-y" or a == "--yes" then yes = true
  elseif ROLES[a] then roleArg = a
  elseif J.looksLike(a) then joinArg = a
  else printError("ignoring unknown argument: " .. tostring(a)) end
end

local function color(c) if term.isColor() then term.setTextColor(c) end end

--- key: preset name that answers this question without asking.
local function ask(prompt, default, key)
  color(colors.yellow)
  write(prompt)
  if default ~= nil and default ~= "" then
    color(colors.lightGray)
    write(" [" .. tostring(default) .. "]")
  end
  color(colors.white)
  write(": ")
  if key and preset[key] ~= nil then
    print(preset[key])
    return preset[key] ~= "" and preset[key] or default
  end
  if yes and default ~= nil then
    print(tostring(default))
    return default
  end
  local s = read()
  s = s and s:gsub("^%s+", ""):gsub("%s+$", "") or ""
  if s == "" then return default end
  return s
end

local function askNumber(prompt, default, key)
  while true do
    local n = tonumber(ask(prompt, default, key))
    if n then return n end
    color(colors.red)
    print("Please enter a number.")
    if key then preset[key] = nil end
  end
end

local function genSecret()
  math.randomseed(os.epoch("utc") + os.getComputerID() * 7919)
  local chars = "abcdefghjkmnpqrstuvwxyz23456789"
  local out = {}
  for i = 1, 20 do
    local k = math.random(1, #chars)
    out[i] = chars:sub(k, k)
  end
  return table.concat(out)
end

term.clear()
term.setCursorPos(1, 1)
color(colors.lime)
print("TurtleGPS setup  -  this is computer #" .. os.getComputerID())
color(colors.white)

local old = config.load() or {}
local kind = turtle and "turtle" or (pocket and "pocket" or "computer")
local defaultRole = roleArg or old.role or (kind == "turtle" and "turtle" or (kind == "pocket" and "pocket" or nil))
local role = roleArg
while not ROLES[role] do
  role = ask("Role (control, turtle, pocket, gpshost)", defaultRole)
  if not ROLES[role] then yes = false end
end
if roleArg then print("Role: " .. role) end

-- keep hand-edited settings when re-running setup for the same role
local cfg = { role = role }
if old.role == role then
  for k, v in pairs(old) do cfg[k] = v end
end

if role == "control" then
  local secret = ask("Shared secret (blank = generate)", old.secret, "secret")
  if not secret or #secret < 8 then
    secret = genSecret()
    color(colors.lime)
    print("Generated a new secret.")
    color(colors.white)
  end
  cfg.secret = secret
else
  local id, secret
  if joinArg then
    id, secret = J.parse(joinArg)
    if not id then
      color(colors.red)
      print(secret)
      secret = nil
    end
  end
  while not id do
    local s = ask("Join code (press J on the control computer), or Enter to type secret + ID", nil)
    if not s then break end
    local why
    id, why = J.parse(s)
    if id then
      secret = why
    else
      color(colors.red)
      print(why)
    end
  end
  if id then
    color(colors.lime)
    print("Joined control computer #" .. id)
    color(colors.white)
  else
    repeat
      secret = ask("Shared secret (same as control)", old.secret, "secret")
      if not secret or #secret < 8 then
        color(colors.red)
        print("At least 8 characters.")
        preset.secret = nil
      end
    until secret and #secret >= 8
    id = askNumber("Control computer ID", old.serverId, "server")
  end
  cfg.secret, cfg.serverId = secret, id
end

if role == "control" or role == "gpshost" then
  local d
  repeat
    d = P.normDim(ask("Dimension of this computer (overworld, nether, end)", old.dim or "overworld", "dim"))
    if not d then preset.dim = nil end
  until d
  cfg.dim = d
elseif role == "turtle" then
  local d = ask("Dimension (overworld, nether, end; blank = from GPS)", old.dim or "", "dim")
  cfg.dim = P.normDim(d)
end

if role == "gpshost" then
  print("This computer's block coordinates (F3, look at it: 'Targeted Block'):")
  cfg.x = askNumber("x", old.x, "x")
  cfg.y = askNumber("y", old.y, "y")
  cfg.z = askNumber("z", old.z, "z")
end

if role == "control" then
  cfg.owner = ask("Your player name (for Chat Box alerts)", old.owner, "owner")
  local ids = ask("Pocket computer IDs allowed to command (comma separated)",
    old.commanders and table.concat(old.commanders, ",") or "", "commanders")
  cfg.commanders = {}
  for n in tostring(ids or ""):gmatch("%d+") do cfg.commanders[#cfg.commanders + 1] = tonumber(n) end
end

if role == "pocket" then
  cfg.owner = ask("Your player name", old.owner, "owner")
end

if role == "turtle" or role == "pocket" then
  local label = ask("Label", preset.label or os.getComputerLabel() or old.label or (role .. os.getComputerID()), "label")
  if label then
    cfg.label = label
    os.setComputerLabel(label)
  end
end

local problems = config.problems(cfg)
if #problems > 0 then
  color(colors.red)
  for _, p in ipairs(problems) do print(p) end
  return
end

if not fs.exists("/fleet/data") then fs.makeDir("/fleet/data") end
config.save(cfg)
local startup = 'shell.run("/fleet/boot.lua")\n'
if fs.exists("/startup.lua") then
  local h = fs.open("/startup.lua", "r")
  local cur = h.readAll()
  h.close()
  if cur ~= startup then
    if fs.exists("/startup.lua.bak") then fs.delete("/startup.lua.bak") end
    fs.move("/startup.lua", "/startup.lua.bak")
    print("Old /startup.lua saved as /startup.lua.bak")
  end
end
local h = fs.open("/startup.lua", "w")
h.write(startup)
h.close()

color(colors.lime)
print("Saved /fleet/config.lua")
color(colors.white)
if role == "control" then
  print("Join code for every other fleet computer (keep it private; also: press J later):")
  color(colors.yellow)
  print(J.make(os.getComputerID(), cfg.secret))
  color(colors.white)
  print("Add garages etc. with: edit /fleet/config.lua")
else
  print("Check this computer any time with /fleet/bin/doctor")
end
local again = ask("Reboot now? (y/n)", "y")
if again == "y" or again == "Y" then os.reboot() end
]]
FILES["boot.lua"] = [[
-- TurtleGPS launcher, started by /startup.lua.
-- Runs this computer's role program and restarts it after a crash. If freshly updated
-- code crashes 3 times before running for a minute, the previous code is restored.
-- Hold Ctrl+T to stop and get a shell.

package.path = "/fleet/?.lua;/fleet/?/init.lua;" .. package.path

local config = require("lib.config")
local store = require("lib.store")
local Up = require("lib.update")

local APPS = { control = "app.control", turtle = "app.turtle", pocket = "app.pocket", gpshost = "app.gpshost" }

local function fail(lines)
  if term.isColor() then term.setTextColor(colors.red) end
  for _, l in ipairs(lines) do print(l) end
  term.setTextColor(colors.white)
  print("Run /fleet/bin/setup  or  edit /fleet/config.lua")
end

local cfg, err = config.load()
if not cfg then
  fail({ "TurtleGPS: cannot read /fleet/config.lua", tostring(err) })
  return
end
local problems = config.problems(cfg)
if #problems > 0 then
  fail(problems)
  return
end
if cfg.label and not os.getComputerLabel() then os.setComputerLabel(cfg.label) end

local function crashLog(msg)
  pcall(function()
    local h = fs.open("/fleet/data/crash.txt", "a")
    h.writeLine(os.epoch("utc") .. " " .. tostring(msg))
    h.close()
  end)
end

local crashes = 0
while true do
  local ok, perr
  local loaded, main = pcall(require, APPS[cfg.role])
  if not loaded then
    ok, perr = false, main
  else
    parallel.waitForAny(function()
      ok, perr = xpcall(function() main(cfg) end, debug.traceback)
    end, function()
      -- after a minute of running, new code counts as good
      sleep(60)
      local st = store.load(Up.STATE, {})
      if st.pending then
        st.pending, st.crashes = false, 0
        store.save(Up.STATE, st)
      end
      crashes = 0
      os.pullEvent("fleet_never")
    end)
  end
  if ok then return end
  if tostring(perr):find("Terminated", 1, true) then
    print("TurtleGPS stopped.")
    return
  end

  term.setCursorPos(1, 1)
  term.clear()
  if term.isColor() then term.setTextColor(colors.red) end
  print("TurtleGPS crashed:")
  print(tostring(perr))
  term.setTextColor(colors.white)
  crashLog(perr)

  local st = store.load(Up.STATE, {})
  if st.pending then
    st.crashes = (st.crashes or 0) + 1
    store.save(Up.STATE, st)
    if st.crashes >= 3 and Up.rollback() then
      print("New code keeps crashing: rolled back. Rebooting.")
      crashLog("rolled back update " .. tostring(st.ver))
      sleep(2)
      os.reboot()
    end
  end
  crashes = crashes + 1
  local delay = math.min(60, 5 * crashes)
  print("Restarting in " .. delay .. "s (hold Ctrl+T to stop)")
  sleep(delay)
  for name in pairs(package.loaded) do
    if name:match("^app%.") then package.loaded[name] = nil end
  end
end
]]
FILES["lib/config.lua"] = [[
-- Loads /fleet/config.lua (a Lua file returning a table) and fills in defaults per role.
-- Edit it in-game with:  edit /fleet/config.lua

local U = require("lib.util")

local C = {}
C.PATH = "/fleet/config.lua"
C.DATA = "/fleet/data"

C.DEFAULTS = {
  all = {
    role = nil,          -- "control" | "turtle" | "pocket" | "gpshost"
    secret = nil,        -- shared secret, identical on every fleet computer
    serverId = nil,      -- computer ID of the control-room computer
    dim = nil,           -- this computer's dimension (turtles/gps hosts/control)
    replayWindow = 30,   -- seconds a signed message stays valid
  },
  turtle = {
    heartbeat = 3,       -- seconds between heartbeats
    gpsEvery = 60,       -- seconds between GPS re-fixes while idle
    reservedSlots = { 16 }, -- slot 16 holds the swap tool (pickaxe <-> modem)
    lowFuel = 500,       -- report low fuel below this (plus distance home)
  },
  control = {
    dim = "overworld",
    commanders = {},     -- computer IDs allowed to send commands (pockets, extra UIs)
    turtles = nil,       -- optional allowlist of turtle IDs; nil = any computer with the secret
    staleAfter = 12,     -- seconds without heartbeat before a turtle is shown stale
    lostAfter = 45,      -- seconds without heartbeat before a turtle is LOST (alert)
    lowFuel = 500,
    owner = nil,         -- player name for Chat Box alerts
    monitor = { side = nil, scale = nil }, -- scale nil = pick 1 or 0.5 from the monitor size
    garages = {},        -- [dim] = { x = , y = , z = }  shown on the map
    ui = { ascii = false },
  },
  pocket = {
    owner = nil,         -- your player name (matches Player Detector results)
    refresh = 2,
    ui = { ascii = false },
  },
  gpshost = {
    x = nil, y = nil, z = nil,
  },
}

local function readConfigFile(path)
  if not fs.exists(path) then return nil, "missing" end
  local h = fs.open(path, "r")
  local src = h.readAll()
  h.close()
  local fn, err = load(src, "=config", "t", {})
  if not fn then return nil, err end
  local ok, t = pcall(fn)
  if not ok then return nil, t end
  if type(t) ~= "table" then return nil, "config.lua must return a table" end
  return t
end

--- Returns config table (with defaults) or nil plus an error.
function C.load(path)
  local t, err = readConfigFile(path or C.PATH)
  if not t then return nil, err end
  U.merge(t, C.DEFAULTS.all)
  if t.role and C.DEFAULTS[t.role] then U.merge(t, C.DEFAULTS[t.role]) end
  return t
end

--- Lists human readable problems with a config.
function C.problems(cfg)
  local p = {}
  local roles = { control = true, turtle = true, pocket = true, gpshost = true }
  if not roles[cfg.role] then p[#p + 1] = "role must be control, turtle, pocket or gpshost" end
  if type(cfg.secret) ~= "string" or #cfg.secret < 8 then
    p[#p + 1] = "secret must be at least 8 characters"
  end
  if cfg.role ~= "control" and type(cfg.serverId) ~= "number" then
    p[#p + 1] = "serverId must be the control computer's ID"
  end
  if cfg.role == "gpshost" then
    if type(cfg.x) ~= "number" or type(cfg.y) ~= "number" or type(cfg.z) ~= "number" then
      p[#p + 1] = "gpshost needs x, y, z of this computer"
    end
    if not cfg.dim then p[#p + 1] = "gpshost needs dim" end
  end
  return p
end

-- Readable Lua output so the file stays hand-editable.
local function pretty(v, indent)
  local t = type(v)
  if t == "string" then return string.format("%q", v) end
  if t ~= "table" then return tostring(v) end
  local pad = string.rep("  ", indent + 1)
  local parts = {}
  local n = #v
  for i = 1, n do parts[#parts + 1] = pad .. pretty(v[i], indent + 1) end
  for _, k in ipairs(U.sortedKeys(v)) do
    if not (type(k) == "number" and k >= 1 and k <= n) then
      local key = (type(k) == "string" and k:match("^[%a_][%w_]*$")) and k or ("[" .. pretty(k, 0) .. "]")
      parts[#parts + 1] = pad .. key .. " = " .. pretty(v[k], indent + 1)
    end
  end
  if #parts == 0 then return "{}" end
  return "{\n" .. table.concat(parts, ",\n") .. ",\n" .. string.rep("  ", indent) .. "}"
end

function C.save(cfg, path)
  path = path or C.PATH
  local keep = {}
  local defaults = C.DEFAULTS[cfg.role] or {}
  for k, v in pairs(cfg) do
    -- only write keys that differ from defaults, so new defaults reach old installs
    local d = defaults[k]
    if d == nil then d = C.DEFAULTS.all[k] end
    if type(v) == "table" or v ~= d then keep[k] = v end
  end
  local h = fs.open(path, "w")
  h.write("-- TurtleGPS fleet config. Same secret on every fleet computer.\n")
  h.write("return " .. pretty(keep, 0) .. "\n")
  h.close()
end

C.pretty = pretty

return C
]]
FILES["lib/doctor.lua"] = [[
-- Self-check for any fleet computer. Each check yields { level, title, detail } where
-- level is "pass", "warn", "fail" or "info"; failures carry a hint on how to fix them.
-- Used by bin/doctor (prints) and bin/report (attaches to the bug report).

local P = require("lib.proto")
local U = require("lib.util")
local config = require("lib.config")
local Net = require("lib.net")
local locate = require("lib.locate")
local store = require("lib.store")
local sha2 = require("lib.sha2")
local Up = require("lib.update")

local D = {}

local function yield()
  os.queueEvent("fleet_yield")
  os.pullEvent("fleet_yield")
end

local function checkCode(add)
  local m = Up.readManifest()
  if not m then
    add("warn", "Code", "no /fleet/manifest: reinstall so updates can be checked")
    return
  end
  local bad, n = {}, 0
  for _, path in ipairs(U.sortedKeys(m.files)) do
    n = n + 1
    local data = store.readFile("/fleet/" .. path)
    if not data then bad[#bad + 1] = path .. " (missing)"
    elseif sha2.sha256Hex(data) ~= m.files[path] then bad[#bad + 1] = path .. " (edited)" end
    yield()
  end
  if #bad > 0 then
    add("warn", "Code", ("version %s, but %d file(s) differ: %s. Reinstall to repair."):format(
      m.ver, #bad, table.concat(bad, ", ")))
  else
    add("pass", "Code", ("version %s, %d files intact"):format(m.ver, n))
  end
end

local function checkDisk(add)
  local free = fs.getFreeSpace("/")
  local kb = math.floor(free / 1024)
  if free < 20000 then
    add("fail", "Disk", kb .. " KB free: logs and state can't be saved. Delete files or raise computerSpaceLimit.")
  elseif free < 100000 then
    add("warn", "Disk", kb .. " KB free")
  else
    add("pass", "Disk", kb .. " KB free")
  end
end

local function pingControl(cfg, add)
  local net = Net.new({ secret = cfg.secret, dim = P.normDim(cfg.dim) or "unknown", window = cfg.replayWindow })
  if not net:open() then return nil end
  local t0 = os.epoch("utc")
  net:send(cfg.serverId, { type = P.PING, role = cfg.role })
  local timer = os.startTimer(4)
  while true do
    local ev, a, b, c = os.pullEvent()
    if ev == "rednet_message" then
      local from, body = net:unwrap(a, b, c)
      if from == cfg.serverId and body.type == P.PONG then
        os.cancelTimer(timer)
        add("pass", "Control", ("#%d answered in %d ms (%s)"):format(from, os.epoch("utc") - t0, P.dimLabel(body.dim)))
        local mine = Up.myVersion()
        if body.ver and body.ver ~= "none" and body.ver ~= mine then
          add("info", "Update", ("control runs code %s, this computer %s: it updates itself shortly"):format(body.ver, mine))
        end
        if cfg.role == "turtle" and body.turtleAllowed == false then
          add("fail", "Allowlist", "control has a `turtles` allowlist without #" .. os.getComputerID() .. ": add it there")
        end
        if cfg.role == "pocket" and not body.commander then
          add("warn", "Allowlist", ("#%d is not in the control's `commanders` list: it can view but not command"):format(
            os.getComputerID()))
        end
        return body
      end
    elseif ev == "timer" and a == timer then
      add("fail", "Control", ("no reply from #%d in 4 s. Check: control running? serverId right? same secret? "
        .. "(the control's own screen shows 'last rejected: #%d bad signature' if the secret differs)"):format(
        cfg.serverId, os.getComputerID()))
      return nil
    end
  end
end

local function checkGps(cfg, add, optional)
  local pos, err, fixes = locate.locate(3, { all = true })
  fixes = pos and pos.fixes or fixes or {}
  if not pos then
    add(optional and "info" or "fail", "GPS", ("%s (heard %d host(s) in this dimension). Run /fleet/bin/gpscheck"):format(
      tostring(err), #fixes))
    return nil
  end
  add("pass", "GPS", ("%d, %d, %d in %s, from %d hosts"):format(pos.bx, pos.by, pos.bz,
    pos.dim and P.dimLabel(pos.dim) or "unknown dimension", pos.n))
  if pos.res > 0.5 then
    add("warn", "GPS", ("hosts disagree by %.1f blocks: a host's coordinates are wrong (gpscheck shows which)"):format(pos.res))
  end
  if pos.cond < 0.01 then add("warn", "GPS", "hosts are nearly on one plane: raise or lower one") end
  if not pos.dim then
    add("warn", "GPS", "hosts don't report a dimension (stock gps hosts?): run the TurtleGPS gpshost role on them")
  elseif cfg.dim and P.normDim(cfg.dim) ~= pos.dim then
    add("warn", "Dimension", ("config says %s but GPS says %s: fix dim in /fleet/config.lua"):format(
      P.dimLabel(P.normDim(cfg.dim)), P.dimLabel(pos.dim)))
  end
  return pos
end

local function checkGpsPeers(cfg, add)
  local modem, side = U.findWirelessModem()
  local ch = locate.CHANNEL
  local wasOpen = modem.isOpen(ch)
  if not wasOpen then modem.open(ch) end
  modem.transmit(ch, ch, "PING")
  local me = { x = cfg.x, y = cfg.y, z = cfg.z }
  local peers, seen, bad = {}, {}, {}
  local timer = os.startTimer(2)
  while true do
    local ev, s, c, _, msg, dist = os.pullEvent()
    if ev == "modem_message" and s == side and c == ch and dist and type(msg) == "table"
        and tonumber(msg[1]) and tonumber(msg[2]) and tonumber(msg[3]) then
      local p = { x = tonumber(msg[1]), y = tonumber(msg[2]), z = tonumber(msg[3]) }
      local key = p.x .. "," .. p.y .. "," .. p.z
      if not seen[key] then
        seen[key] = true
        peers[#peers + 1] = p
        local expect = math.sqrt((p.x - me.x) ^ 2 + (p.y - me.y) ^ 2 + (p.z - me.z) ^ 2)
        if math.abs(expect - dist) >= 0.5 then
          bad[#bad + 1] = ("%s (measured %.1f, coordinates say %.1f)"):format(U.fmtPos(p), dist, expect)
        end
      end
    elseif ev == "timer" and s == timer then
      break
    end
  end
  if not wasOpen then modem.close(ch) end
  local points = { me }
  for _, p in ipairs(peers) do points[#points + 1] = p end
  if #peers == 0 then
    add("fail", "GPS", "no other GPS hosts answer in this dimension: need 4 in total, all running and chunk-loaded")
  elseif #bad == #peers and #peers >= 2 then
    add("fail", "GPS", ("this host's x y z (%s) look wrong: all %d peers disagree. Re-run setup with the "
      .. "Targeted Block coordinates."):format(U.fmtPos(me), #peers))
  elseif #bad > 0 then
    add("warn", "GPS", "peer(s) with wrong coordinates: " .. table.concat(bad, "; "))
  elseif #points < 4 then
    add("fail", "GPS", ("%d hosts in total: need at least 4"):format(#points))
  elseif locate.spread(points) < 1e-3 then
    add("warn", "GPS", "hosts are (nearly) on one plane: raise or lower one")
  else
    add("pass", "GPS", ("%d other hosts agree with this host's coordinates %s"):format(#peers, U.fmtPos(me)))
  end
end

local function checkTurtle(cfg, add)
  local chunky
  for _, side in ipairs({ "left", "right" }) do
    if peripheral.getType(side) == "chunky" then chunky = side end
  end
  if chunky then
    add("pass", "Chunky", "Chunky upgrade on the " .. chunky .. ": keeps this chunk loaded")
  else
    add("warn", "Chunky", "no Chunky Turtle upgrade found: this turtle stops when you walk away")
  end
  if cfg.role ~= "turtle" then return end
  local fuel = turtle.getFuelLevel()
  if fuel == "unlimited" then
    add("pass", "Fuel", "unlimited (server config)")
  elseif fuel < 2 then
    add("fail", "Fuel", fuel .. ": it needs fuel to move one block and learn its heading. Put coal in and run 'refuel'")
  elseif fuel < (cfg.lowFuel or 500) then
    add("warn", "Fuel", fuel .. " (low)")
  else
    add("pass", "Fuel", tostring(fuel))
  end
  local tool = turtle.getItemDetail(16)
  if tool and tool.name:find("pickaxe") then
    add("pass", "Slot 16", tool.name .. " (swap tool for digging)")
  elseif tool then
    add("warn", "Slot 16", tool.name .. " is in slot 16, which is reserved for the swap pickaxe")
  else
    add("warn", "Slot 16", "empty: put a diamond pickaxe there before milestone 3 (digging jobs)")
  end
  local nav = store.load("/fleet/data/nav", nil)
  if type(nav) == "table" and nav.x then
    add("info", "Saved position", ("%s facing %s"):format(U.fmtPos(nav), nav.h and P.HEADING_NAME[nav.h] or "?"))
  end
end

local function explainChat(err)
  err = tostring(err)
  if err:find("incorrect player") then return "player is offline or the owner name is misspelled" end
  if err:find("NOT_SAME_DIMENSION") then return "server's AP config has chatBoxMultiDimensional = false" end
  if err:lower():find("cooldown") then return "Chat Box on cooldown: run doctor again in a few seconds" end
  return err
end

local function checkControl(cfg, add)
  local mon, any
  for _, name in ipairs(peripheral.getNames()) do
    if peripheral.getType(name) == "monitor" then
      any = name
      if peripheral.call(name, "isColor") then mon = name; break end
    end
  end
  if mon then
    local m = peripheral.wrap(mon)
    local w, h = m.getSize()
    local scale = m.getTextScale and m.getTextScale() or "?"
    add("pass", "Monitor", ("advanced monitor '%s': %dx%d characters at text scale %s"):format(mon, w, h, tostring(scale)))
  elseif any then
    add("warn", "Monitor", "monitor '" .. any .. "' is not an advanced monitor (no colour or touch): use advanced ones")
  else
    add("warn", "Monitor", "no monitor attached: the map shows on this computer's screen")
  end

  local chat = peripheral.find("chatBox")
  if not chat then
    add("info", "Chat Box", "not attached: alerts only show on the monitor")
  elseif not cfg.owner then
    add("warn", "Chat Box", "attached, but `owner` isn't set in /fleet/config.lua, so alerts aren't sent")
  else
    local ok, res, err = pcall(chat.sendMessageToPlayer, "doctor test: Chat Box alerts reach you", cfg.owner, "TurtleGPS")
    if ok and res then
      add("pass", "Chat Box", "test message sent to " .. cfg.owner)
    else
      add("warn", "Chat Box", "test message to " .. cfg.owner .. " failed: " .. explainChat(ok and err or res))
    end
  end

  local speaker = peripheral.find("speaker")
  if speaker then
    pcall(speaker.playNote, "bell", 1, 12)
    add("pass", "Speaker", "attached (you should have heard a chime)")
  else
    add("info", "Speaker", "not attached: no alert chime")
  end

  local det = peripheral.find("playerDetector")
  if not det then
    add("info", "Player Detector", "not attached (milestone 2 shows players with it; pockets can report instead)")
  else
    local okList, online = pcall(det.getOnlinePlayers)
    local who = cfg.owner or (okList and type(online) == "table" and online[1])
    if not who then
      add("info", "Player Detector", "attached; set `owner` to test it")
    else
      local ok, pos = pcall(det.getPlayerPos, who)
      if not ok then
        local msg = tostring(pos)
        if msg:find("disabled") then
          add("warn", "Player Detector", "getPlayerPos is disabled in the server's Advanced Peripherals config "
            .. "(playerSpy). Milestone 2 then uses pocket GPS instead.")
        else
          add("warn", "Player Detector", msg)
        end
      elseif type(pos) == "table" and pos.x then
        add("pass", "Player Detector", ("sees %s at %d, %d, %d in %s"):format(who, pos.x, pos.y, pos.z,
          P.dimLabel(P.normDim(pos.dimension))))
      else
        add("warn", "Player Detector", "can't see " .. who .. " (offline, or in another dimension with "
          .. "playerDetMultiDimensional off)")
      end
    end
  end

  if #(cfg.commanders or {}) == 0 then
    add("info", "Commanders", "no pocket IDs allowed yet (needed from milestone 2)")
  else
    add("pass", "Commanders", "pockets allowed to command: #" .. table.concat(cfg.commanders, ", #"))
  end
  local garages = {}
  for d, g in pairs(cfg.garages or {}) do
    if type(g) == "table" and g.x then garages[#garages + 1] = ("%s %s"):format(P.dimShort(P.normDim(d) or d), U.fmtPos(g)) end
  end
  if #garages == 0 then
    add("info", "Garages", "none set: add garages = { overworld = { x=, y=, z= } } to /fleet/config.lua")
  else
    add("pass", "Garages", table.concat(garages, "; "))
  end
  local db = store.load("/fleet/data/fleet.db", nil)
  if type(db) == "table" then
    local t, lost, g = 0, 0, 0
    for _, r in pairs(db.turtles or {}) do
      t = t + 1
      if r.link == "lost" then lost = lost + 1 end
    end
    for _ in pairs(db.gps or {}) do g = g + 1 end
    add("info", "Fleet", ("knows %d turtle(s) (%d lost) and %d GPS host(s)"):format(t, lost, g))
  end
end

--- Runs every check that applies to this computer. opts.out(result) is called as each
--- result arrives. Returns the list of results and counts { pass, warn, fail, info }.
function D.run(opts)
  opts = opts or {}
  local results, counts = {}, { pass = 0, warn = 0, fail = 0, info = 0 }
  local function add(level, title, detail)
    local r = { level = level, title = title, detail = detail }
    results[#results + 1] = r
    counts[level] = counts[level] + 1
    if opts.out then opts.out(r) end
  end

  local kind = turtle and "turtle" or (pocket and "pocket computer" or "computer")
  add("info", "Computer", ("#%d %s (%s), %s"):format(os.getComputerID(), os.getComputerLabel() or "no label", kind,
    _HOST or os.version()))

  local cfg, err = config.load()
  if not cfg then
    add("fail", "Config", "cannot read /fleet/config.lua (" .. tostring(err) .. "): run /fleet/bin/setup")
    return results, counts
  end
  local problems = config.problems(cfg)
  for _, p in ipairs(problems) do add("fail", "Config", p .. ": run /fleet/bin/setup") end
  if #problems > 0 then return results, counts end
  add("pass", "Config", "role " .. cfg.role .. (cfg.dim and (", " .. P.dimLabel(P.normDim(cfg.dim))) or "")
    .. (cfg.serverId and (", control #" .. cfg.serverId) or ""))

  local startup = store.readFile("/startup.lua")
  if startup and startup:find("/fleet/boot.lua", 1, true) then
    add("pass", "Startup", "/startup.lua starts TurtleGPS")
  else
    add("warn", "Startup", "/startup.lua doesn't start TurtleGPS on boot: run /fleet/bin/setup")
  end
  checkCode(add)
  checkDisk(add)

  local modem, side = U.findWirelessModem()
  if not modem then
    add("fail", "Modem", "no wireless modem attached: attach an ENDER modem")
  else
    add("pass", "Modem", "wireless modem on " .. side .. " (it must be an ender modem)")
  end

  if modem and cfg.role ~= "control" then pingControl(cfg, add) end
  if modem then
    if cfg.role == "gpshost" then checkGpsPeers(cfg, add)
    else checkGps(cfg, add, cfg.role == "control") end
  end
  if turtle then checkTurtle(cfg, add) end
  if cfg.role == "control" then checkControl(cfg, add) end
  if cfg.role == "pocket" and not cfg.owner then
    add("warn", "Owner", "set owner = \"YourName\" so the map can show you")
  end
  return results, counts
end

local TAGS = { pass = "OK  ", warn = "WARN", fail = "FAIL", info = "info" }
D.TAGS = TAGS

function D.format(r)
  return ("[%s] %s: %s"):format(TAGS[r.level], r.title, r.detail or "")
end

return D
]]
FILES["lib/joincode.lua"] = [[
-- Join codes: the control computer's ID and the shared secret in one pasteable string,
-- with a short checksum so a typo is caught instead of producing a silent bad config.
--   TG-<control id>-<secret>-<4 hex checksum>

local sha2 = require("lib.sha2")

local J = {}

local function checksum(id, secret)
  return sha2.sha256Hex(id .. ":" .. secret):sub(1, 4)
end

function J.make(id, secret)
  return ("TG-%d-%s-%s"):format(id, secret, checksum(id, secret))
end

function J.looksLike(s)
  return type(s) == "string" and s:match("^%s*[Tt][Gg]%-%d+%-.+%-%x%x%x%x%s*$") ~= nil
end

--- Returns controlId, secret  or  nil, reason.
function J.parse(s)
  if type(s) ~= "string" then return nil, "not a join code" end
  s = s:gsub("^%s+", ""):gsub("%s+$", "")
  local id, secret, chk = s:match("^[Tt][Gg]%-(%d+)%-(.+)%-(%x%x%x%x)$")
  if not id then return nil, "not a join code (it looks like TG-7-abcd...-1f2e)" end
  id = tonumber(id)
  if checksum(id, secret) ~= chk:lower() then
    return nil, "join code has a typo (checksum does not match)"
  end
  return id, secret
end

return J
]]
FILES["lib/locate.lua"] = [[
-- Dimension-aware GPS.
--
-- Our GPS hosts answer pings with { x, y, z, dim = "the_nether" }. Stock gps.locate still
-- accepts that (it only checks #msg == 3), and this locator also learns the dimension.
-- Ender modems deliver cross-dimension messages WITHOUT a distance, so only hosts in our
-- own dimension can contribute a fix.
--
-- Position is solved by least squares over all hosts heard, which also yields a residual
-- that exposes a host with mistyped coordinates.

local U = require("lib.util")
local P = require("lib.proto")

local L = {}
L.CHANNEL = 65534 -- same channel as the built-in gps API

--- fixes: list of { p = {x,y,z}, d = distance }. Returns pos {x,y,z,res,cond} or nil, reason.
function L.solve(fixes)
  local n = #fixes
  if n < 4 then return nil, "need 4 GPS hosts, heard " .. n end
  local p1, d1 = fixes[1].p, fixes[1].d
  local a11, a12, a13, a22, a23, a33 = 0, 0, 0, 0, 0, 0
  local r1, r2, r3 = 0, 0, 0
  for i = 2, n do
    local f = fixes[i]
    local qx, qy, qz = f.p.x - p1.x, f.p.y - p1.y, f.p.z - p1.z
    local c = 0.5 * (qx * qx + qy * qy + qz * qz - f.d * f.d + d1 * d1)
    a11, a12, a13 = a11 + qx * qx, a12 + qx * qy, a13 + qx * qz
    a22, a23, a33 = a22 + qy * qy, a23 + qy * qz, a33 + qz * qz
    r1, r2, r3 = r1 + qx * c, r2 + qy * c, r3 + qz * c
  end
  local det = a11 * (a22 * a33 - a23 * a23) - a12 * (a12 * a33 - a23 * a13) + a13 * (a12 * a23 - a22 * a13)
  local tr = (a11 + a22 + a33) / 3
  local cond = tr > 0 and math.abs(det) / (tr * tr * tr) or 0
  if cond < 1e-6 then return nil, "GPS hosts are coplanar (move one up or down)" end
  local x = (r1 * (a22 * a33 - a23 * a23) - a12 * (r2 * a33 - a23 * r3) + a13 * (r2 * a23 - a22 * r3)) / det
  local y = (a11 * (r2 * a33 - a23 * r3) - r1 * (a12 * a33 - a23 * a13) + a13 * (a12 * r3 - r2 * a13)) / det
  local z = (a11 * (a22 * r3 - r2 * a23) - a12 * (a12 * r3 - r2 * a13) + r1 * (a12 * a23 - a22 * a13)) / det
  local pos = { x = p1.x + x, y = p1.y + y, z = p1.z + z, cond = cond }
  local res = 0
  for i = 1, n do
    local f = fixes[i]
    local dx, dy, dz = pos.x - f.p.x, pos.y - f.p.y, pos.z - f.p.z
    local r = math.abs(math.sqrt(dx * dx + dy * dy + dz * dz) - f.d)
    f.res = r
    if r > res then res = r end
  end
  pos.res = res
  return pos
end

--- Solves, and if the result is inconsistent and there are spare hosts, drops the
--- host that disagrees (e.g. a stranger's misconfigured GPS host).
function L.robustSolve(fixes)
  local pos, err = L.solve(fixes)
  if not pos or pos.res <= 0.5 or #fixes < 5 then return pos, err end
  local best
  for skip = 1, #fixes do
    local sub = {}
    for i, f in ipairs(fixes) do if i ~= skip then sub[#sub + 1] = f end end
    local p = L.solve(sub)
    if p and (not best or p.res < best.res) then
      best = p
      best.dropped = fixes[skip]
    end
  end
  if best and best.res < pos.res then return best end
  return pos
end

--- How three-dimensional a set of host positions is: 0 = coplanar, ~1 = well spread.
function L.spread(points)
  if #points < 4 then return 0 end
  local p1 = points[1]
  local a11, a12, a13, a22, a23, a33 = 0, 0, 0, 0, 0, 0
  for i = 2, #points do
    local qx, qy, qz = points[i].x - p1.x, points[i].y - p1.y, points[i].z - p1.z
    a11, a12, a13 = a11 + qx * qx, a12 + qx * qy, a13 + qx * qz
    a22, a23, a33 = a22 + qy * qy, a23 + qy * qz, a33 + qz * qz
  end
  local det = a11 * (a22 * a33 - a23 * a23) - a12 * (a12 * a33 - a23 * a13) + a13 * (a12 * a23 - a22 * a13)
  local tr = (a11 + a22 + a33) / 3
  if tr <= 0 then return 0 end
  return math.abs(det) / (tr * tr * tr)
end

local function majorityDim(fixes)
  local count, best, bestN = {}, nil, 0
  for _, f in ipairs(fixes) do
    if f.dim then
      count[f.dim] = (count[f.dim] or 0) + 1
      if count[f.dim] > bestN then best, bestN = f.dim, count[f.dim] end
    end
  end
  return best
end

--- Pings GPS hosts. opts.all = wait the full timeout and return every host heard.
--- Returns pos { x, y, z (floats), bx, by, bz (block coords), dim, n, res, fixes } or nil, reason.
function L.locate(timeout, opts)
  opts = opts or {}
  local modem, side = U.findWirelessModem()
  if not modem then return nil, "no wireless modem" end
  local wasOpen = modem.isOpen(L.CHANNEL)
  if not wasOpen then modem.open(L.CHANNEL) end
  modem.transmit(L.CHANNEL, L.CHANNEL, "PING")

  local fixes, seen = {}, {}
  local timer = os.startTimer(timeout or 2)
  local pos
  while true do
    local ev, a, b, c, d, e = os.pullEvent()
    if ev == "modem_message" then
      if a == side and b == L.CHANNEL and c == L.CHANNEL and e and type(d) == "table"
          and tonumber(d[1]) and tonumber(d[2]) and tonumber(d[3]) then
        local key = d[1] .. "," .. d[2] .. "," .. d[3]
        if not seen[key] then
          seen[key] = true
          fixes[#fixes + 1] = {
            p = { x = tonumber(d[1]), y = tonumber(d[2]), z = tonumber(d[3]) },
            d = e, dim = P.normDim(d.dim),
          }
          if not opts.all and #fixes >= 4 then
            pos = L.solve(fixes)
            if pos and pos.res <= 0.5 then break end
            pos = nil
          end
        end
      end
    elseif ev == "timer" and a == timer then
      timer = nil
      break
    end
  end
  if timer then os.cancelTimer(timer) end
  if not wasOpen then modem.close(L.CHANNEL) end

  local use = fixes
  local ours = {}
  for _, f in ipairs(fixes) do if f.dim then ours[#ours + 1] = f end end
  if #ours >= 4 then use = ours end
  local err
  if not pos then pos, err = L.robustSolve(use) end
  if not pos then return nil, err, fixes end
  pos.bx, pos.by, pos.bz = math.floor(pos.x + 0.5), math.floor(pos.y + 0.5), math.floor(pos.z + 0.5)
  pos.dim = majorityDim(use)
  pos.n = #use
  pos.fixes = fixes
  return pos
end

return L
]]
FILES["lib/log.lua"] = [[
-- Logger: keeps the last lines in memory (for on-screen consoles) and appends to a
-- size-capped file so in-game problems can be reported afterwards.

local L = {}
L.__index = L

local LEVELS = { debug = 1, info = 2, warn = 3, error = 4 }

--- opts: path (file, optional), keep (lines in memory), maxBytes (rotate size), echo (print lines)
function L.new(opts)
  opts = opts or {}
  return setmetatable({
    path = opts.path,
    keep = opts.keep or 40,
    maxBytes = opts.maxBytes or 24000,
    echo = opts.echo,
    level = LEVELS[opts.level or "info"] or 2,
    lines = {},
    seq = 0,
  }, L)
end

function L:write(level, fmt, ...)
  if (LEVELS[level] or 2) < self.level then return end
  local ok, msg = pcall(string.format, fmt, ...)
  if not ok then msg = tostring(fmt) end
  local t = os.epoch("utc")
  local secs = math.floor(t / 1000) % 86400
  local stamp = string.format("%02d:%02d:%02d", math.floor(secs / 3600), math.floor(secs / 60) % 60, secs % 60)
  local line = stamp .. " " .. level:sub(1, 1):upper() .. " " .. msg
  self.seq = self.seq + 1
  local lines = self.lines
  lines[#lines + 1] = { seq = self.seq, level = level, text = line }
  if #lines > self.keep then table.remove(lines, 1) end
  if self.echo then print(line) end
  if self.path then self:append(line) end
end

function L:append(line)
  pcall(function()
    if fs.exists(self.path) and fs.getSize(self.path) > self.maxBytes then
      local old = self.path .. ".old"
      if fs.exists(old) then fs.delete(old) end
      fs.move(self.path, old)
    end
    local h = fs.open(self.path, "a")
    if h then
      h.writeLine(line)
      h.close()
    end
  end)
end

function L:debug(...) self:write("debug", ...) end
function L:info(...) self:write("info", ...) end
function L:warn(...) self:write("warn", ...) end
function L:error(...) self:write("error", ...) end

return L
]]
FILES["lib/net.lua"] = [[
-- Signed rednet messaging over ender modems.
--
-- Every message is an envelope:
--   { v = 1, f = fromId, t = toId|-1, ts = epochMs, n = nonce, b = "<serialized body>", m = hmac }
-- m = HMAC-SHA256(secret, "v|f|t|ts|n|b"). The secret itself is never transmitted.
-- Receivers drop anything that is not ours, too old, replayed, or badly signed, before
-- unserializing it. Who may do *what* (allowlists) is decided by the caller.

local sha2 = require("lib.sha2")
local ser = require("lib.ser")
local P = require("lib.proto")
local U = require("lib.util")

local Net = {}
Net.__index = Net

--- opts: secret, dim (string or function returning one), window (seconds), maxBody (bytes)
function Net.new(opts)
  local self = setmetatable({}, Net)
  self.secret = assert(opts.secret, "net: secret required")
  self.id = os.getComputerID()
  self.window = (opts.window or 30) * 1000
  self.maxBody = opts.maxBody or 65536
  self.protocol = opts.protocol or P.PROTOCOL
  if type(opts.dim) == "function" then self.dimFn = opts.dim
  else
    local d = opts.dim
    self.dimFn = function() return d end
  end
  self.seq = 0
  self.seen, self.seenCount = {}, 0
  self.stats = { sent = 0, recv = 0, rejected = 0, reasons = {}, last = {} }
  math.randomseed(os.epoch("utc") % 2147483647 + self.id * 7919)
  return self
end

--- Opens rednet on the first wireless modem. Returns true if one is available.
function Net:open()
  if self.side and peripheral.getType(self.side) == "modem" and rednet.isOpen(self.side) then
    return true
  end
  local _, side = U.findWirelessModem()
  self.side = side
  if not side then return false end
  if not rednet.isOpen(side) then rednet.open(side) end
  return true
end

function Net:isUp()
  return self.side ~= nil and peripheral.getType(self.side) == "modem" and rednet.isOpen(self.side)
end

local function isInt(x)
  return type(x) == "number" and x == math.floor(x) and x > -1e15 and x < 1e16
end

local function macInput(e)
  return string.format("%d|%d|%d|%d|%s|%s", e.v, e.f, e.t, e.ts, e.n, e.b)
end

function Net:wrap(to, body)
  if body.dim == nil then body.dim = self.dimFn() end
  self.seq = self.seq + 1
  local e = {
    v = P.VERSION, f = self.id, t = to, ts = os.epoch("utc"),
    n = string.format("%x.%x", self.seq, math.random(0, 0xffffff)),
    b = ser.serialize(body),
  }
  e.m = sha2.hmacHex(self.secret, macInput(e))
  return e
end

--- Sends a body table to one computer. Returns false if no modem is available.
function Net:send(to, body)
  if not self:open() then return false end
  rednet.send(to, self:wrap(to, body), self.protocol)
  self.stats.sent = self.stats.sent + 1
  return true
end

function Net:broadcast(body)
  if not self:open() then return false end
  rednet.broadcast(self:wrap(P.BROADCAST, body), self.protocol)
  self.stats.sent = self.stats.sent + 1
  return true
end

function Net:reject(sender, reason)
  local s = self.stats
  s.rejected = s.rejected + 1
  s.reasons[reason] = (s.reasons[reason] or 0) + 1
  table.insert(s.last, 1, { from = sender, reason = reason, t = os.epoch("utc") })
  if #s.last > 8 then table.remove(s.last) end
  return nil, reason
end

function Net:pruneSeen(now)
  if self.seenCount < 400 then return end
  local n = 0
  for k, exp in pairs(self.seen) do
    if exp < now then self.seen[k] = nil else n = n + 1 end
  end
  self.seenCount = n
end

--- Checks a rednet_message. Returns fromId, body  or  nil, reason.
--- Messages for other protocols or other computers return nil without counting as rejected.
function Net:unwrap(sender, e, protocol)
  if protocol ~= self.protocol then return nil, "protocol" end
  if type(e) ~= "table" then return self:reject(sender, "format") end
  if not isInt(e.t) then return self:reject(sender, "format") end
  if e.t ~= self.id and e.t ~= P.BROADCAST then return nil, "not for me" end
  if e.v ~= P.VERSION or not isInt(e.f) or not isInt(e.ts)
      or type(e.n) ~= "string" or type(e.b) ~= "string" or type(e.m) ~= "string" then
    return self:reject(sender, "format")
  end
  if #e.b > self.maxBody or #e.n > 40 then return self:reject(sender, "too big") end
  if e.f ~= sender then return self:reject(sender, "sender mismatch") end
  local now = os.epoch("utc")
  if math.abs(now - e.ts) > self.window then return self:reject(sender, "expired") end
  local key = e.f .. ":" .. e.n
  if self.seen[key] then return self:reject(sender, "replay") end
  if sha2.hmacHex(self.secret, macInput(e)) ~= e.m then return self:reject(sender, "bad signature") end
  self.seen[key] = e.ts + self.window
  self.seenCount = self.seenCount + 1
  self:pruneSeen(now)
  local body = ser.unserialize(e.b)
  if type(body) ~= "table" or type(body.type) ~= "string" then return self:reject(sender, "body") end
  body.dim = P.normDim(body.dim)
  self.stats.recv = self.stats.recv + 1
  return e.f, body
end

--- Blocks until a valid message arrives (or timeout). Other events are discarded,
--- so only call this from a coroutine dedicated to receiving.
function Net:receive(timeout)
  local timer = timeout and os.startTimer(timeout)
  while true do
    local ev, a, b, c = os.pullEvent()
    if ev == "rednet_message" then
      local from, body = self:unwrap(a, b, c)
      if from then
        if timer then os.cancelTimer(timer) end
        return from, body
      end
    elseif ev == "timer" and a == timer then
      return nil
    end
  end
end

return Net
]]
FILES["lib/proto.lua"] = [[
-- Protocol constants shared by every fleet program.

local P = {}

P.PROTOCOL = "turtlegps"   -- rednet protocol name
P.VERSION = 1              -- envelope format version
P.BROADCAST = -1           -- envelope "to" value for broadcasts

-- Message types. Every body is a table { type = ..., dim = <sender's dimension>, ... }.
P.HB = "hb"                -- turtle -> server: heartbeat / telemetry
P.HB_ACK = "hb_ack"        -- server -> turtle: heartbeat acknowledged (+ queued commands later)
P.VIEW_REQ = "view_req"    -- ui client -> server: give me the map view for a dimension
P.VIEW = "view"            -- server -> ui client
P.ACTION = "action"        -- ui client -> server: forget turtle, ack alert, ... (allowlisted)
P.ACTION_R = "action_r"    -- server -> ui client: result of an action
P.ALERT = "alert"          -- server -> ui clients: a new alert was raised
P.UPD_OFFER = "upd_offer"  -- server -> all: new code version available
P.UPD_REQ = "upd_req"      -- device -> server: send me the files I am missing
P.UPD_FILE = "upd_file"    -- server -> device: one file
P.UPD_END = "upd_end"      -- server -> device: manifest, all files sent
P.PING = "ping"            -- any fleet computer -> control: are you there? (doctor)
P.PONG = "pong"            -- control -> asker: yes, plus what it thinks of the asker

-- Headings: 0 = north (-z), 1 = east (+x), 2 = south (+z), 3 = west (-x)
P.HEADING_NAME = { [0] = "N", [1] = "E", [2] = "S", [3] = "W" }
P.DX = { [0] = 0, [1] = 1, [2] = 0, [3] = -1 }
P.DZ = { [0] = -1, [1] = 0, [2] = 1, [3] = 0 }

function P.headingFromDelta(dx, dz)
  if dx == 0 and dz == -1 then return 0 end
  if dx == 1 and dz == 0 then return 1 end
  if dx == 0 and dz == 1 then return 2 end
  if dx == -1 and dz == 0 then return 3 end
  return nil
end

-- Dimensions. Canonical ids drop the "minecraft:" prefix.
P.DIM_ORDER = { "overworld", "the_nether", "the_end" }

local aliases = {
  overworld = "overworld", ow = "overworld", world = "overworld",
  nether = "the_nether", the_nether = "the_nether",
  ["end"] = "the_end", the_end = "the_end",
}

function P.normDim(d)
  if type(d) ~= "string" or d == "" then return nil end
  d = d:lower()
  local short = d:match("^minecraft:(.+)$") or d
  return aliases[short] or d
end

local labels = { overworld = "Overworld", the_nether = "Nether", the_end = "End" }

function P.dimLabel(d)
  if not d then return "Unknown" end
  if labels[d] then return labels[d] end
  local s = d:match(":(.+)$") or d
  return (s:gsub("_", " "):gsub("^%l", string.upper))
end

local shorts = { overworld = "OVR", the_nether = "NTH", the_end = "END" }

function P.dimShort(d)
  if shorts[d] then return shorts[d] end
  return P.dimLabel(d):sub(1, 3):upper()
end

return P
]]
FILES["lib/ser.lua"] = [=[
-- Compact, deterministic serializer (keys sorted) and a sandboxed unserializer.
-- Same output in-game and in the mock harness, so signatures and saved files match.

local format, concat, sort = string.format, table.concat, table.sort
local floor, huge = math.floor, math.huge

local M = {}

local escapes = { ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t", ['"'] = '\\"', ["\\"] = "\\\\" }

local function quote(s)
  return '"' .. s:gsub('[%c"\\\128-\255]', function(c)
    return escapes[c] or format("\\%03d", c:byte())
  end) .. '"'
end

local function num(n)
  if n ~= n then return "0/0" end
  if n == huge then return "1/0" end
  if n == -huge then return "-1/0" end
  if n == floor(n) and n >= -9007199254740992 and n <= 9007199254740992 then
    return format("%d", n)
  end
  local s = format("%.14g", n)
  if tonumber(s) ~= n then s = format("%.17g", n) end
  return s
end

local keywords = {}
for w in ([[and break do else elseif end false for function goto if in
  local nil not or repeat return then true until while]]):gmatch("%a+") do keywords[w] = true end

local function keyOrder(a, b)
  local ta, tb = type(a), type(b)
  if ta ~= tb then return ta < tb end
  return a < b
end

local function write(v, out, seen)
  local t = type(v)
  if t == "string" then out[#out + 1] = quote(v)
  elseif t == "number" then out[#out + 1] = num(v)
  elseif t == "boolean" or t == "nil" then out[#out + 1] = tostring(v)
  elseif t == "table" then
    if seen[v] then error("ser: cannot serialize a table that contains itself", 0) end
    seen[v] = true
    out[#out + 1] = "{"
    local n = #v
    for i = 1, n do
      write(v[i], out, seen)
      out[#out + 1] = ","
    end
    local keys = {}
    for k in pairs(v) do
      local tk = type(k)
      if not (tk == "number" and k >= 1 and k <= n and k == floor(k)) then
        if tk ~= "string" and tk ~= "number" and tk ~= "boolean" then
          error("ser: cannot serialize key of type " .. tk, 0)
        end
        keys[#keys + 1] = k
      end
    end
    sort(keys, keyOrder)
    for _, k in ipairs(keys) do
      if type(k) == "string" and k:match("^[%a_][%w_]*$") and not keywords[k] then
        out[#out + 1] = k
      else
        out[#out + 1] = "["
        write(k, out, seen)
        out[#out + 1] = "]"
      end
      out[#out + 1] = "="
      write(v[k], out, seen)
      out[#out + 1] = ","
    end
    if out[#out] == "," then out[#out] = "}" else out[#out + 1] = "}" end
    seen[v] = nil
  else
    error("ser: cannot serialize a " .. t, 0)
  end
end

function M.serialize(v)
  local out = {}
  write(v, out, {})
  return concat(out)
end

--- Returns the value, or nil plus an error message. Runs with an empty environment.
function M.unserialize(s)
  if type(s) ~= "string" then return nil, "not a string" end
  local fn, err = load("return " .. s, "=ser", "t", {})
  if not fn then return nil, err end
  local ok, v = pcall(fn)
  if not ok then return nil, v end
  return v
end

return M
]=]
FILES["lib/sha2.lua"] = [[
-- SHA-256 and HMAC-SHA256 in pure Lua (CC:Tweaked / Lua 5.2, uses bit32).
-- Used to sign every fleet message so the shared secret never goes over the air.

local band, bxor, bnot = bit32.band, bit32.bxor, bit32.bnot
local rrotate, rshift = bit32.rrotate, bit32.rshift
local byte, char, rep, format = string.byte, string.char, string.rep, string.format
local concat = table.concat

local K = {
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
